const inp = $('When Called').first().json;
const it = $input.first() ? $input.first().json : {};
const sc = (it && it.statusCode != null) ? Number(it.statusCode) : null;
const body = (it && it.body !== undefined) ? it.body : null;
const headers = (it && it.headers) ? it.headers : {};
const sp = (inp.success_path || '').toString().trim();
function deepGet(o, p) { if (!p) return o; const ps = p.split('.'); let c = o; for (const k of ps) { if (c == null) return undefined; c = c[k]; } return c; }
let ok = (sc != null && sc >= 200 && sc < 300 && body != null);
if (ok && sp) { const v = deepGet(body, sp); ok = (v != null && v !== ''); }
let primaryModel = '';
try { primaryModel = (JSON.parse(inp.request_body) || {}).model || ''; } catch (e) {}
const model_used = (body && body.model && String(body.model).trim()) ? String(body.model).trim() : primaryModel;
return [{ json: { ok: ok, fell_back: false, model_used: model_used, body: body, headers: headers } }];

const inp = $('When Called').first().json;
let b = {};
try { b = JSON.parse(inp.request_body) || {}; } catch (e) { b = {}; }
const primaryModel = b.model || '';
const fb = (inp.fallback_model || '').toString().trim();
b.model = fb || primaryModel;
return [{ json: {
  endpoint_url: inp.endpoint_url,
  fb_request_body: JSON.stringify(b),
  extra_headers: inp.extra_headers || '{}',
  success_path: inp.success_path || '',
  fb_model: b.model
} }];

const inp = $('When Called').first().json;
const prep = $('Prep Fallback Body').first().json;
const it = $input.first() ? $input.first().json : {};
const sc = (it && it.statusCode != null) ? Number(it.statusCode) : null;
const body = (it && it.body !== undefined) ? it.body : null;
const headers = (it && it.headers) ? it.headers : {};
const sp = (inp.success_path || '').toString().trim();
function deepGet(o, p) { if (!p) return o; const ps = p.split('.'); let c = o; for (const k of ps) { if (c == null) return undefined; c = c[k]; } return c; }
let ok = (sc != null && sc >= 200 && sc < 300 && body != null);
if (ok && sp) { const v = deepGet(body, sp); ok = (v != null && v !== ''); }
if (!ok) { throw new Error('Call Model with Fallback: primary and fallback both failed (fallback status=' + sc + ', model=' + (prep.fb_model || '') + ')'); }
const model_used = (body && body.model && String(body.model).trim()) ? String(body.model).trim() : (prep.fb_model || '');
return [{ json: { ok: true, fell_back: true, model_used: model_used, body: body, headers: headers } }];
